def construct_array(X, d):
    if X == 1:
        return [1]

    result = []
    current = 1
    while X > 0 and len(result) < 10000:
        count = 0
        while (1 << count) <= X:
            count += 1
        count -= 1
        value = current
        for _ in range(count):
            result.append(value)
            value *= d
        X -= (1 << count) - 1
        current += 1

    if X > 0:
        return [-1]
    else:
        return [len(result), *result]

# Read input
X, d = map(int, input().split())

# Get the result
result = construct_array(X, d)

# Print the result
if result == [-1]:
    print(-1)
else:
    print(result[0])
    print(*result[1:])
